bool resolve_bool_expression(struct xkb_context *ctx, const ExprDef *expr, bool *set_rtrn) {
    switch (expr->type) {
        case EXPR_BOOL: {
            if (expr->u.boolean == TRUE)
                *set_rtrn = true;
            else if (expr->u.boolean == FALSE)
                *set_rtrn = false;
            else {
                xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Invalid boolean value in expression.\n");
                return false;
            }
            return true;
        }

        case EXPR_IDENT: {
            if (strcmp(expr->u.ident, "true") == 0) {
                *set_rtrn = true;
                return true;
            } else if (strcmp(expr->u.ident, "false") == 0) {
                *set_rtrn = false;
                return true;
            } else {
                xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Unknown boolean identifier '%s' in expression.\n", expr->u.ident);
                return false;
            }
        }

        case EXPR_FIELD: {
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Field references are not supported in boolean expressions.\n");
            return false;
        }

        case EXPR_OP: {
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Boolean expression does not support operations.\n");
            return false;
        }

        default:
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR, "Unsupported expression type in boolean resolution.\n");
            return false;
    }
}

bool resolve_bool_expr(struct xkb_context *ctx, const ExprDef *expr, bool *set_rtrn) {
    if (expr == NULL || set_rtrn == NULL)
        return false;

    switch (expr->type) {
        case EXPR_BOOLEAN: {
            if (expr->value.b) {
                *set_rtrn = true;
                return true;
            } else {
                *set_rtrn = false;
                return true;
            }
        }
        case EXPR_IDENT: {
            if (strcmp(expr->value.s, "true") == 0) {
                *set_rtrn = true;
                return true;
            } else if (strcmp(expr->value.s, "false") == 0) {
                *set_rtrn = false;
                return true;
            } else {
                xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR,
                                "Unknown identifier: %s", expr->value.s);
                return false;
            }
        }
        case EXPR_FIELD_REF:
        case EXPR_UNARY_NOT:
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR,
                            "Unsupported operation in boolean expression.");
            return false;
        default:
            xkb_context_log(ctx, XKB_LOG_LEVEL_ERROR,
                            "Unknown expression type for boolean resolution.");
            return false;
    }
}

bool resolve_bool_expr(struct xkb_context *ctx, const ExprDef *expr, bool *set_rtrn) {
    switch (expr->type) {
        case EXPR_BOOL: {
            if (expr->value.bool_val.has_value) {
                *set_rtrn = expr->value.bool_val.value;
                return true;
            }
            break;
        }

        case EXPR_IDENT: {
            if (!strcmp(expr->value.ident.value, "true") || !strcmp(expr->value.ident.value, "1")) {
                *set_rtrn = true;
                return true;
            } else if (!strcmp(expr->value.ident.value, "false") || !strcmp(expr->value.ident.value, "0")) {
                *set_rtrn = false;
                return true;
            }
            xkb_context_log(ctx, XKB_LOG_MESSAGE_ERROR, "Unknown boolean identifier: %s", expr->value.ident.value);
            break;
        }

        default: {
            xkb_context_log(ctx, XKB_LOG_MESSAGE_ERROR, "Unsupported operation for boolean resolution: %d", expr->type);
            break;
        }
    }

    return false;
}

